const $=s=>document.querySelector(s), money=n=>'$'+Math.max(0,n).toLocaleString('en-AU');
function init(count=2,names=[]){players=Array.from({length:count},(_,i)=>({name:names[i]||people[i].name,token:people[i].token,color:people[i].color,pos:0,cash:1500,active:true,jail:0}));turn=0;spacesOwned={};round=1;rolled=false;lock=false;buildMode=false;logs=[];logs.push('New game! The coast is yours to explore.');drawBoard();render();$('#die1').textContent='⚀';$('#die2').textContent='⚀';$('#turnHint').textContent='Tap roll to head out. Buy a spot or pay rent when you land.'}
function drawBoard(){const board=$('#board');board.querySelectorAll('.tile').forEach(e=>e.remove());spaces.forEach((s,i)=>{let r,c,edge;if(i<=10){r=11;c=11-i;edge='bottom'}else if(i<=20){r=21-i;c=1;edge='left'}else if(i<=30){r=1;c=i-19;edge='top'}else{r=i-29;c=11;edge='right'}let el=document.createElement('div');el.className=`tile edge-${edge} ${[0,10,20,30].includes(i)?'corner':''}`;el.style.gridRow=r;el.style.gridColumn=c;el.dataset.index=i;el.setAttribute('aria-label',s.n);if(s.g)el.style.setProperty('--band',groups[s.g]);if(s.t==='property')el.innerHTML=`<div class="tile-band"></div><span class="tile-name">${s.n}</span><span class="tile-price">${money(s.p)}</span>`;else el.innerHTML=`<span class="tile-icon">${s.icon||''}</span><span class="tile-name">${s.n}</span>${s.p?`<span class="tile-price">${money(s.p)}</span>`:''}`;board.appendChild(el)});renderTiles()}
function renderTiles(){document.querySelectorAll('.tile').forEach((el,i)=>{el.querySelectorAll('.token,.owner-dot').forEach(x=>x.remove());const owner=spacesOwned[i];if(owner){const dot=document.createElement('span');dot.className='owner-dot';dot.style.background=players[owner.player].color;dot.title=`Owned by ${players[owner.player].name}`;el.appendChild(dot)}players.forEach((p,pi)=>{if(p.active&&p.pos===i){const token=document.createElement('span');token.className='token';token.textContent=p.token;token.style.background=p.color;token.title=p.name;el.appendChild(token)}})})}
function addLog(text,icon='✦'){logs.unshift({text,icon});logs=logs.slice(0,8);$('#gameLog').innerHTML=logs.map(x=>`<div class="log-line"><i>${x.icon}</i><span>${x.text}</span></div>`).join('')}
function render(){if(!players.length)return;const p=players[turn];$('#turnName').textContent=p.name;$('#turnSub').textContent=p.jail?`On a short visit to the lock-up · ${p.jail} turn left`:'A fresh start on the coast';$('#roundLabel').textContent=`ROUND ${round}`;$('#roundStat').textContent=round;$('#bankStat').textContent=players.filter(x=>x.active).length;$('#rollBtn').disabled=rolled||lock||!p.active||players.filter(x=>x.active).length<2;$('#rollBtn').innerHTML=rolled?'Rolled this turn ✓':'Roll the dice <span>→</span>';$('#endBtn').disabled=!rolled||lock;$('#buildBtn').disabled=!rolled||lock||!hasMonopoly(turn);$('#turnHint').textContent=rolled?'Buy, build, or finish your turn.':'Tap roll to head out. Buy a spot or pay rent when you land.';$('#playersList').innerHTML=players.map((x,i)=>`<div class="player-row ${i===turn?'current':''}" style="${!x.active?'opacity:.45':''}"><div class="player-avatar" style="background:${x.color}22">${x.token}</div><div class="player-info"><b>${x.name}${!x.active?' · out':''}</b><small>${x.pos===0?'At Start':spaces[x.pos].n}</small></div><div class="player-cash">${money(x.cash)}</div></div>`).join('');const mine=Object.entries(spacesOwned).filter(([i,o])=>o.player===turn&&spaces[+i].t!=='rail'&&spaces[+i].t!=='utility');$('#portfolioCount').textContent=`${Object.values(spacesOwned).filter(o=>o.player===turn).length} HELD`;$('#propertyList').innerHTML=Object.keys(spacesOwned).length?Object.entries(spacesOwned).filter(([i,o])=>o.player===turn).map(([i,o])=>{let s=spaces[+i];return `<div class="property-chip"><i style="background:${s.g?groups[s.g]:s.t==='rail'?'#9b7955':'#63a9ad'}"></i><span>${s.n}${s.t==='property'&&o.houses?` · ${o.houses<5?'🏠'.repeat(o.houses):'🏨 Hotel'}`:''}</span><b>${money(s.p)}</b></div>`}).join('')||'<div class="tiny-label">No patches held yet.</div>':'<div class="tiny-label">Your first patch is waiting.</div>';$('#ownedStat').textContent=Object.keys(spacesOwned).length;renderTiles()}
function hasMonopoly(pi){return Object.entries(groups).some(([g])=>{let ids=spaces.map((s,i)=>s.g===g?i:-1).filter(x=>x>=0);return ids.length&&ids.every(i=>spacesOwned[i]?.player===pi)})}
function ownsGroup(pi,g){return spaces.map((s,i)=>s.g===g?i:-1).filter(x=>x>=0).every(i=>spacesOwned[i]?.player===pi)}
function rentAt(index,owner){let s=spaces[index],o=spacesOwned[index];if(s.t==='property'){let base=s.r[o.houses||0];if(!o.houses&&ownsGroup(owner,s.g))base*=2;return base}if(s.t==='rail'){let count=Object.entries(spacesOwned).filter(([i,x])=>x.player===owner&&spaces[+i].t==='rail').length;return 25*2**(count-1)}if(s.t==='utility'){let count=Object.entries(spacesOwned).filter(([i,x])=>x.player===owner&&spaces[+i].t==='utility').length;return (count===2?10:4)*(lastRoll[0]+lastRoll[1])}return 0}
let lastRoll=[1,1];function pay(from,to,amount,reason){amount=Math.min(amount,Math.max(0,from.cash));from.cash-=amount;if(to)to.cash+=amount;addLog(`${from.name} paid ${money(amount)} ${reason}.`,'💸');if(from.cash<=0)bankrupt(from)}function bankrupt(p){p.active=false;Object.entries(spacesOwned).forEach(([i,o])=>{if(o.player===players.indexOf(p))delete spacesOwned[i]});addLog(`${p.name} is out of the game. The coast is still open!`,'🫣')}
function moveTo(p,target,collect=true){let old=p.pos;if(target<old&&collect){p.cash+=200;addLog(`${p.name} passed Start and collected $200.`,'☀️')}p.pos=target;renderTiles()}
function openModal(html){$('#modal').innerHTML=html;$('#modalBackdrop').classList.add('show')}
function closeModal(){ $('#modalBackdrop').classList.remove('show') }
function modalMessage(title,text,emoji='🌴',button='Lovely',callback=()=>{}){openModal(`<div class="modal-kicker">A little coastal update</div><h2>${title}</h2><p>${text}</p><div class="card-face community"><div class="card-emoji">${emoji}</div></div><div class="modal-actions"><button class="modal-btn primary" id="modalDone">${button}</button></div>`);$('#modalDone').onclick=()=>{closeModal();callback()}}
function rollDice(){if(rolled||lock)return;lock=true;const d1=$('#die1'),d2=$('#die2');d1.classList.add('rolling');d2.classList.add('rolling');playSound(440,.08);setTimeout(()=>{lastRoll=[1+Math.floor(Math.random()*6),1+Math.floor(Math.random()*6)];const faces=['⚀','⚁','⚂','⚃','⚄','⚅'];d1.textContent=faces[lastRoll[0]-1];d2.textContent=faces[lastRoll[1]-1];d1.classList.remove('rolling');d2.classList.remove('rolling');lock=false;rolled=true;const p=players[turn],steps=lastRoll[0]+lastRoll[1];addLog(`${p.name} rolled ${lastRoll[0]} + ${lastRoll[1]} and moved ${steps}.`,'🎲');if(p.jail){p.jail=0;moveTo(p,(p.pos+steps)%40);land(p)}else{let target=p.pos+steps;if(target>=40){p.cash+=200;addLog(`${p.name} passed Start and collected $200.`,'☀️')}p.pos=target%40;renderTiles();land(p)}render()},650)}
function land(p){const i=p.pos,s=spaces[i],owner=spacesOwned[i];if(s.t==='property'||s.t==='rail'||s.t==='utility'){if(!owner){if(p.cash>=s.p){openModal(`<div class="modal-kicker">Fresh patch on the coast</div><h2>${s.n}</h2><p>This spot is still part of the commons. Buy it for <b>${money(s.p)}</b> and add it to your little corner of the coast?</p><div class="card-face" style="background:${s.g?groups[s.g]+'55':'#f2d783'}"><div class="card-emoji">${s.icon||'🏡'}</div><div class="card-text">${s.t==='property'?'A local place to call your own':'A useful bit of the coast'}</div></div><div class="modal-actions"><button class="modal-btn" id="skipBuy">Not today</button><button class="modal-btn primary" id="buyIt">Buy for ${money(s.p)}</button></div>`);$('#buyIt').onclick=()=>{p.cash-=s.p;spacesOwned[i]={player:turn,houses:0};addLog(`${p.name} bought ${s.n} for ${money(s.p)}.`,'🏡');closeModal();render()};$('#skipBuy').onclick=()=>{addLog(`${p.name} left ${s.n} for another day.`,'🌾');closeModal();render()}}else modalMessage('A bit out of reach','You don’t have enough in the tin for this one. Keep rolling and build up your balance.','🪙')}else if(owner.player!==turn){let amount=rentAt(i,owner.player);pay(p,players[owner.player],amount,`rent at ${s.n}`);modalMessage('A local rent bill',`${p.name} paid ${money(amount)} rent to ${players[owner.player].name} for landing on ${s.n}.`,'🏠')}}else modalMessage('Your own little patch',`You’ve landed on ${s.n} — a lovely spot you already own.`,'🏡')}
else if(s.t==='tax'){pay(p,null,s.p,'in local rates');modalMessage('Rates are due',`A ${money(s.p)} local rates bill. Not the best surprise, but the roads look tidy.`,'🧾')}else if(s.t==='chance'||s.t==='community'){let deck=s.t==='chance'?chanceCards:communityCards,card=deck[Math.floor(Math.random()*deck.length)];if(card.money>0){p.cash+=card.money;addLog(`${p.name}: ${card.text}`,'📬')}else if(card.money<0)pay(p,null,-card.money,'for a coastal expense');else addLog(`${p.name}: ${card.text}`,'🌀');if(card.move!==undefined){let old=p.pos;if(card.move<old){p.cash+=200;addLog(`${p.name} passed Start and collected $200.`,'☀️')}p.pos=card.move;renderTiles();if(spacesOwned[card.move]&&spacesOwned[card.move].player!==turn){let rent=rentAt(card.move,spacesOwned[card.move].player);pay(p,players[spacesOwned[card.move].player],rent,`rent at ${spaces[card.move].n}`)}}modalMessage(s.t==='chance'?'Chance on the coast':'Community chest',card.text,s.t==='chance'?'🌀':'📬')}else if(s.t==='jail'){p.pos=10;p.jail=1;addLog(`${p.name} was sent to the lock-up for a quiet turn.`,'🔒');modalMessage('Off to the lock-up',`A little timeout at the local lock-up. Next turn you’ll roll and be back on your way.`,'🔒')}else if(s.t==='free'){p.cash+=50;addLog(`${p.name} enjoyed a free arvo and found $50 in the sand.`,'🏖️');modalMessage('Free arvo!',`Take a breath, enjoy the beach and collect $50 from the local good-times fund.`,'🏖️')}else if(s.t==='go'){p.cash+=200;addLog(`${p.name} landed right on Start and collected $200.`,'☀️');modalMessage('Back at Start',`Collect $200 for a lap around our lovely patch of Queensland.`,'☀️')}else{addLog(`${p.name} is just visiting the lock-up.`,'🦀');render()}}

