 function buildPanel(){let mine=Object.entries(spacesOwned).filter(([i,o])=>o.player===turn&&spaces[+i].t==='property');let options=mine.map(([i,o])=>{let s=spaces[+i],cost=Math.max(50,Math.round(s.p*.5));return `<button class="action-btn build-one" data-i="${i}" ${o.houses>=5||players[turn].cash<cost?'disabled':''}>${o.houses===4?'🏨 Hotel':'🏠 '+s.n}<br><small>${o.houses>=5?'Complete':`Add level · ${money(cost)}`}</small></button>`}).join('');openModal(`<div class="modal-kicker">A little more like home</div><h2>Build Queenslanders</h2><p>You own a full colour set. Add classic Queenslander homes to raise rent — five levels makes a grand old hotel. Each house costs half the property's buy price.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:7px;max-height:230px;overflow:auto">${options||'<p>No properties to build on just yet.</p>'}</div><div class="modal-actions"><button class="modal-btn primary" id="closeBuild">Done</button></div>`);$('#closeBuild').onclick=closeModal;document.querySelectorAll('.build-one').forEach(btn=>btn.onclick=()=>{let i=+btn.dataset.i,o=spacesOwned[i],cost=Math.max(50,Math.round(spaces[i].p*.5));if(!o||o.houses>=5||players[turn].cash<cost)return;players[turn].cash-=cost;o.houses++;addLog(`${players[turn].name} added ${o.houses===5?'a Queenslander hotel':'a Queenslander home'} to ${spaces[i].n}.`,'🏠');render();buildPanel()})}
 function playSound(freq=440,duration=.12){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();let osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='triangle';osc.frequency.value=freq;gain.gain.setValueAtTime(.07,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration)}catch(e){}}

