const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true, executablePath:'/home/runner/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome'});
 const page=await browser.newPage({viewport:{width:1280,height:950}, deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://localhost:3002');
 await page.waitForSelector('#rollBtn');
 await page.evaluate(()=>{let vals=[0,.67];Math.random=()=>vals.shift()??0});
 await page.click('#rollBtn');
 await page.waitForSelector('#buyIt',{timeout:3000});
 const offer=await page.locator('#modal').innerText();
 await page.click('#buyIt');
 await page.waitForTimeout(100);
 const afterBuy=await page.evaluate(()=>({cash:document.querySelector('.player-cash').textContent,held:document.querySelector('#portfolioCount').textContent,property:document.querySelector('#propertyList').innerText,owned:document.querySelector('#ownedStat').textContent}));
 await page.click('#endBtn'); await page.waitForTimeout(100);
 const afterTurn=await page.evaluate(()=>({turn:document.querySelector('#turnName').textContent,rollDisabled:document.querySelector('#rollBtn').disabled,round:document.querySelector('#roundLabel').textContent}));
 await page.click('#newGameBtn');
 await page.click('[data-count="3"]');
 await page.locator('#nameFields input').nth(0).fill('Alex');
 await page.locator('#nameFields input').nth(1).fill('Bec');
 await page.locator('#nameFields input').nth(2).fill('Casey');
 await page.click('#startGame'); await page.waitForTimeout(100);
 const setup=await page.evaluate(()=>({turn:document.querySelector('#turnName').textContent,players:[...document.querySelectorAll('.player-info b')].map(e=>e.textContent),count:document.querySelector('#bankStat').textContent,round:document.querySelector('#roundLabel').textContent,modal:document.querySelector('#modalBackdrop').classList.contains('show')}));
 await page.screenshot({path:'/tmp/opencode/coast-final.jpg',type:'jpeg',quality:75,fullPage:true});
 console.log(JSON.stringify({offer,afterBuy,afterTurn,setup,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

